class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}

    def get(self, key: int) -> int:
        if key in self.cache:
            value = self.cache[key]
            # Move accessed item to most recently used
            if key in self.cache:
                value = self.cache.pop(key)
                self.cache[key] = value
            return value
        return -1

    def put(self, key: int, value: int):
        if key in self.cache:
            # Update value and move to most recently used
            self.cache.pop(key)
            self.cache[key] = value
        else:
            # Check capacity before adding new item
            if len(self.cache) >= self.capacity:
                # Evict the least recently used item (the first one inserted, which is the oldest key in the OrderedDict/dict simulation)
                # In a proper implementation using OrderedDict, we'd popitem(last=False)
                # Since we are simulating with standard dicts and relying on usage pattern:
                # To maintain LRU correctly with standard dicts, we need to know insertion order, which standard dicts guarantee insertion order in modern Python (3.7+).
                # The least recently used item is the first item inserted that hasn't been accessed recently.
                lru_key = next(iter(self.cache))
                self.cache.pop(lru_key)

            # Add the new item (which becomes MRU)
            self.cache[key] = value

def rotate_90(matrix: list[list[int]]) -> list[list[int]]:
    n = len(matrix)
    if n == 0:
        return []
    new_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new_matrix[j][n - 1 - i] = matrix[i][j]
    return new_matrix

def two_sum(nums: list[int], target: int) -> list[int]:
    num_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_map:
            return [num_map[complement], i]
        num_map[num] = i

def word_frequency(text: str) -> dict[str, int]:
    if not text:
        return {}
    text = text.lower()
    words = []
    for word in text.split():
        cleaned_word = word.strip(".,!?\'\"").lower()
        if cleaned_word:
            words.append(cleaned_word)

    frequency = {}
    for word in words:
        frequency[word] = frequency.get(word, 0) + 1
    return frequency
